--- LinkRepository.cs ---
using Microsoft.Data.Sqlite;

namespace Service;

/// <summary>
/// The only component that talks to SQLite. Owns schema creation, insert-or-conflict,
/// lookup, and atomic click-increment. See ADR 0001 for the concurrency rationale.
/// </summary>
public sealed class LinkRepository
{
    private readonly string _connectionString;

    public LinkRepository(string connectionString)
    {
        _connectionString = connectionString;
        Initialize();
    }

    private void Initialize()
    {
        using SqliteConnection connection = Open();
        using SqliteCommand cmd = connection.CreateCommand();
        cmd.CommandText = """
            PRAGMA journal_mode=WAL;
            CREATE TABLE IF NOT EXISTS links (
                id           INTEGER PRIMARY KEY AUTOINCREMENT,
                code         TEXT UNIQUE,
                original_url TEXT NOT NULL,
                created_at   TEXT NOT NULL,
                expires_at   TEXT,
                click_count  INTEGER NOT NULL DEFAULT 0
            );
            """;
        cmd.ExecuteNonQuery();
    }

    private SqliteConnection Open()
    {
        SqliteConnection connection = new(_connectionString);
        connection.Open();
        return connection;
    }

    /// <summary>
    /// Inserts a new link. If <paramref name="alias"/> is supplied, attempts that exact code and
    /// returns null if it is already taken (no row created). If not supplied, inserts with a NULL
    /// code, then assigns a base62 code from the resulting rowid, atomically within one transaction.
    /// </summary>
    public async Task<string?> InsertAsync(string? alias, string originalUrl, string createdAt, string? expiresAt)
    {
        using SqliteConnection connection = Open();
        using SqliteTransaction tx = connection.BeginTransaction();

        try
        {
            if (alias is not null)
            {
                using SqliteCommand insert = connection.CreateCommand();
                insert.Transaction = tx;
                insert.CommandText = "INSERT INTO links (code, original_url, created_at, expires_at) VALUES (@code, @url, @created, @expires)";
                insert.Parameters.AddWithValue("@code", alias);
                insert.Parameters.AddWithValue("@url", originalUrl);
                insert.Parameters.AddWithValue("@created", createdAt);
                insert.Parameters.AddWithValue("@expires", (object?)expiresAt ?? DBNull.Value);
                await insert.ExecuteNonQueryAsync();
                tx.Commit();
                return alias;
            }
            else
            {
                using SqliteCommand insert = connection.CreateCommand();
                insert.Transaction = tx;
                insert.CommandText = "INSERT INTO links (code, original_url, created_at, expires_at) VALUES (NULL, @url, @created, @expires); SELECT last_insert_rowid();";
                insert.Parameters.AddWithValue("@url", originalUrl);
                insert.Parameters.AddWithValue("@created", createdAt);
                insert.Parameters.AddWithValue("@expires", (object?)expiresAt ?? DBNull.Value);
                object? idObj = await insert.ExecuteScalarAsync();
                long id = Convert.ToInt64(idObj);
                string code = CodeGenerator.Encode(id);

                using SqliteCommand update = connection.CreateCommand();
                update.Transaction = tx;
                update.CommandText = "UPDATE links SET code = @code WHERE id = @id";
                update.Parameters.AddWithValue("@code", code);
                update.Parameters.AddWithValue("@id", id);
                await update.ExecuteNonQueryAsync();

                tx.Commit();
                return code;
            }
        }
        catch (SqliteException ex) when (ex.SqliteErrorCode == 19) // SQLITE_CONSTRAINT
        {
            tx.Rollback();
            return null;
        }
    }

    public async Task<LinkRecord?> FindByCodeAsync(string code)
    {
        using SqliteConnection connection = Open();
        using SqliteCommand cmd = connection.CreateCommand();
        cmd.CommandText = "SELECT original_url, created_at, expires_at, click_count FROM links WHERE code = @code";
        cmd.Parameters.AddWithValue("@code", code);

        using SqliteDataReader reader = await cmd.ExecuteReaderAsync();

        if (!await reader.ReadAsync())
        {
            return null;
        }

        return new LinkRecord(
            code,
            reader.GetString(0),
            reader.GetString(1),
            reader.IsDBNull(2) ? null : reader.GetString(2),
            reader.GetInt64(3));
    }

    public async Task<bool> IncrementClickCountAsync(string code)
    {
        using SqliteConnection connection = Open();
        using SqliteCommand cmd = connection.CreateCommand();
        cmd.CommandText = "UPDATE links SET click_count = click_count + 1 WHERE code = @code";
        cmd.Parameters.AddWithValue("@code", code);
        int rows = await cmd.ExecuteNonQueryAsync();
        return rows > 0;
    }
}


--- LinkService.cs ---
using System.Globalization;
using System.Text.RegularExpressions;

namespace Service;

public enum CreateOutcome { Ok, AliasTaken, Invalid }

public sealed record CreateLinkResult(CreateOutcome Outcome, string? Code, string? ShortUrl, string? Error);

public enum LookupOutcome { Found, NotFound, Expired }

public sealed record LookupResult(LookupOutcome Outcome, LinkRecord? Link);

/// <summary>
/// Orchestrates create/redirect/stats use cases: validates input, applies URL safety rules,
/// and maps repository/domain outcomes to the results the API host renders as HTTP responses.
/// </summary>
public sealed partial class LinkService
{
    [GeneratedRegex("^[A-Za-z0-9_-]{1,32}$")]
    private static partial Regex AliasPattern();

    private readonly LinkRepository _repository;
    private readonly string _baseUrl;

    public LinkService(LinkRepository repository, string baseUrl)
    {
        _repository = repository;
        _baseUrl = baseUrl;
    }

    public async Task<CreateLinkResult> CreateAsync(CreateLinkRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Url))
        {
            return new CreateLinkResult(CreateOutcome.Invalid, null, null, "url is required");
        }

        if (!UrlSafety.TryValidate(request.Url, out Uri? uri, out string? urlError))
        {
            return new CreateLinkResult(CreateOutcome.Invalid, null, null, urlError);
        }

        string? alias = request.Alias;

        if (alias is not null && !AliasPattern().IsMatch(alias))
        {
            return new CreateLinkResult(CreateOutcome.Invalid, null, null, "alias must match [A-Za-z0-9_-]{1,32}");
        }

        string? expiresAt = null;

        if (!string.IsNullOrWhiteSpace(request.ExpiresAt))
        {
            if (!DateTimeOffset.TryParse(request.ExpiresAt, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out DateTimeOffset parsed))
            {
                return new CreateLinkResult(CreateOutcome.Invalid, null, null, "expiresAt must be ISO-8601 UTC");
            }

            expiresAt = parsed.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ", CultureInfo.InvariantCulture);
        }

        string createdAt = DateTimeOffset.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ", CultureInfo.InvariantCulture);

        string? code = await _repository.InsertAsync(alias, uri!.ToString(), createdAt, expiresAt);

        if (code is null)
        {
            return new CreateLinkResult(CreateOutcome.AliasTaken, null, null, null);
        }

        return new CreateLinkResult(CreateOutcome.Ok, code, $"{_baseUrl}/{code}", null);
    }

    public async Task<LookupResult> RedirectAsync(string code)
    {
        LinkRecord? link = await _repository.FindByCodeAsync(code);

        if (link is null)
        {
            return new LookupResult(LookupOutcome.NotFound, null);
        }

        if (IsExpired(link))
        {
            return new LookupResult(LookupOutcome.Expired, link);
        }

        await _repository.IncrementClickCountAsync(code);
        return new LookupResult(LookupOutcome.Found, link);
    }

    public Task<LinkRecord?> GetStatsAsync(string code) => _repository.FindByCodeAsync(code);

    private static bool IsExpired(LinkRecord link)
    {
        if (link.ExpiresAt is null)
        {
            return false;
        }

        DateTimeOffset expiry = DateTimeOffset.Parse(link.ExpiresAt, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
        return expiry <= DateTimeOffset.UtcNow;
    }
}


--- Program.cs ---
// URL shortener service: create, redirect, and report on shortened links, backed by SQLite.

using Service;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

string dbPath = builder.Configuration["ShortLinks:DbPath"] ?? "links.db";
string baseUrl = (builder.Configuration["ShortLinks:BaseUrl"] ?? "http://localhost:5000").TrimEnd('/');

builder.Services.AddSingleton(new LinkRepository($"Data Source={dbPath}"));
builder.Services.AddSingleton(new LinkService(builder.Services.BuildServiceProvider().GetRequiredService<LinkRepository>(), baseUrl));

WebApplication app = builder.Build();

app.MapGet("/health/live", () => Results.Ok(HealthStatus.Live));

app.MapPost("/api/v1/links", async (CreateLinkRequest? body, LinkService svc) =>
{
    if (body is null)
    {
        return Results.BadRequest(new ErrorResponse("invalid request body"));
    }

    CreateLinkResult result = await svc.CreateAsync(body);

    return result.Outcome switch
    {
        CreateOutcome.Ok => Results.Created($"/{result.Code}", new CreateLinkResponse(result.Code!, result.ShortUrl!)),
        CreateOutcome.AliasTaken => Results.Conflict(new ErrorResponse("alias already taken")),
        _ => Results.BadRequest(new ErrorResponse(result.Error ?? "invalid request")),
    };
});

app.MapGet("/{code}", async (string code, LinkService svc) =>
{
    LookupResult result = await svc.RedirectAsync(code);

    return result.Outcome switch
    {
        LookupOutcome.Found => Results.Redirect(result.Link!.OriginalUrl, permanent: false),
        LookupOutcome.Expired => Results.StatusCode(StatusCodes.Status410Gone),
        _ => Results.NotFound(new ErrorResponse("unknown code")),
    };
});

app.MapGet("/api/v1/links/{code}/stats", async (string code, LinkService svc) =>
{
    LinkRecord? link = await svc.GetStatsAsync(code);

    if (link is null)
    {
        return Results.NotFound(new ErrorResponse("unknown code"));
    }

    return Results.Ok(new LinkStats(link.Code!, link.OriginalUrl, link.CreatedAt, link.ExpiresAt, link.ClickCount));
});

app.Run();

/// <summary>What the liveness endpoint reports.</summary>
public sealed record HealthStatus(string Status)
{
    /// <summary>The service is up.</summary>
    public static HealthStatus Live { get; } = new("live");
}

public sealed record CreateLinkRequest(string? Url, string? Alias, string? ExpiresAt);

public sealed record CreateLinkResponse(string Code, string ShortUrl);

public sealed record LinkStats(string Code, string Url, string CreatedAt, string? ExpiresAt, long ClickCount);

public sealed record ErrorResponse(string Error);


--- README.md ---
# Service skeleton

The starting tree for a run's workspace: a minimal, buildable .NET project that an
implementation stage extends.

It exists so that compensation can be demonstrated against a real version-controlled tree
rather than against throwaway files — a `git revert` that restores an actual project is
evidence; one that restores a scratch file is a formality.

Greenfield runs grow the URL shortener from here.


--- Service.csproj ---
<Project Sdk="Microsoft.NET.Sdk.Web">

  <!-- Target framework, language version and nullability: Directory.Build.props -->

  <PropertyGroup>
    <RootNamespace>Service</RootNamespace>
  </PropertyGroup>

  <ItemGroup>
    <!--
      The test project lives under this one's directory, so the SDK's default glob would
      compile its files into the service. Excluded rather than moved: keeping the service at
      the tree root means every .cs file an implementation stage writes, wherever it puts it,
      is part of the build — and therefore part of what the build gate actually checks. Under
      a src/Service/ layout, a file written one directory off would compile nowhere, pass the
      gate, and ship as inert code nobody noticed.
    -->
    <Compile Remove="tests/**" />
    <Content Remove="tests/**" />
    <None Remove="tests/**" />
  </ItemGroup>

  <ItemGroup>
    <PackageReference Include="Microsoft.Data.Sqlite" />
  </ItemGroup>

</Project>


--- UrlSafety.cs ---
using System.Net;
using System.Net.Sockets;

namespace Service;

/// <summary>
/// Pure validation of a candidate URL: scheme allow-list, and literal-IP host range checks.
/// Never performs DNS resolution; only inspects the string form of the parsed host.
/// </summary>
public static class UrlSafety
{
    public static bool TryValidate(string rawUrl, out Uri? uri, out string? error)
    {
        uri = null;
        error = null;

        if (string.IsNullOrWhiteSpace(rawUrl) || !Uri.TryCreate(rawUrl, UriKind.Absolute, out Uri? parsed))
        {
            error = "url is missing or not a valid absolute URI";
            return false;
        }

        if (parsed.Scheme != Uri.UriSchemeHttp && parsed.Scheme != Uri.UriSchemeHttps)
        {
            error = "url scheme must be http or https";
            return false;
        }

        string host = parsed.Host;

        if (IPAddress.TryParse(host, out IPAddress? ip) && IsDisallowed(ip))
        {
            error = "url host is a loopback, link-local, or private IP literal";
            return false;
        }

        uri = parsed;
        return true;
    }

    private static bool IsDisallowed(IPAddress ip)
    {
        if (ip.AddressFamily == AddressFamily.InterNetwork)
        {
            byte[] b = ip.GetAddressBytes();

            if (b[0] == 127) return true; // loopback
            if (b[0] == 169 && b[1] == 254) return true; // link-local
            if (b[0] == 10) return true; // 10.0.0.0/8
            if (b[0] == 172 && b[1] >= 16 && b[1] <= 31) return true; // 172.16.0.0/12
            if (b[0] == 192 && b[1] == 168) return true; // 192.168.0.0/16
            return false;
        }

        if (ip.AddressFamily == AddressFamily.InterNetworkV6)
        {
            if (IPAddress.IsLoopback(ip)) return true; // ::1

            byte[] b = ip.GetAddressBytes();

            if ((b[0] & 0xFE) == 0xFC) return true; // fc00::/7 unique local
            if (b[0] == 0xFE && (b[1] & 0xC0) == 0x80) return true; // fe80::/10 link-local

            return false;
        }

        return false;
    }
}


--- contracts/openapi.yaml ---
openapi: 3.1.0
info:
  title: URL Shortener Service
  version: "1.0.0"
  description: >
    Creates shortened links, redirects short codes to their original URL while counting
    clicks, and reports per-link statistics. Backed by SQLite; see the design document for
    internal behavior.
servers:
  - url: /
paths:
  /api/v1/links:
    post:
      operationId: createLink
      summary: Create a shortened link
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/CreateLinkRequest'
      responses:
        '201':
          description: Link created
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/CreateLinkResponse'
        '400':
          description: >
            Invalid request: missing url, malformed url, disallowed scheme, private/loopback/
            link-local IP-literal host, malformed alias, or malformed expiresAt.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
        '409':
          description: The requested alias is already taken. No row was created.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
  /{code}:
    get:
      operationId: redirectToOriginal
      summary: Redirect to the original URL and count the click
      parameters:
        - name: code
          in: path
          required: true
          schema:
            type: string
            pattern: '^[A-Za-z0-9_-]{1,32}$'
      responses:
        '302':
          description: Redirect to the original URL. Click count incremented by 1.
          headers:
            Location:
              description: The original URL.
              schema:
                type: string
                format: uri
        '404':
          description: No link exists for this code.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
        '410':
          description: The link exists but has expired. Click count not incremented.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
  /api/v1/links/{code}/stats:
    get:
      operationId: getLinkStats
      summary: Get statistics for a link
      parameters:
        - name: code
          in: path
          required: true
          schema:
            type: string
            pattern: '^[A-Za-z0-9_-]{1,32}$'
      responses:
        '200':
          description: Link statistics
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/LinkStats'
        '404':
          description: No link exists for this code.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
components:
  schemas:
    CreateLinkRequest:
      type: object
      required:
        - url
      additionalProperties: false
      properties:
        url:
          type: string
          format: uri
          description: >
            The URL to shorten. Must have scheme http or https. Must not have a literal
            IP host in a loopback, link-local, or private (RFC 1918 / IPv6 equivalent) range.
            Hostnames (non-literal) are accepted without DNS resolution.
          examples:
            - "https://example.com/a/long/path?x=1"
        alias:
          type: string
          pattern: '^[A-Za-z0-9_-]{1,32}$'
          description: Optional custom short code. Must not already be in use.
          examples:
            - "my-link"
        expiresAt:
          type: string
          format: date-time
          description: >
            Optional ISO-8601 UTC expiry timestamp. May be in the past, in which case the
            link is created already expired.
          examples:
            - "2030-01-01T00:00:00Z"
    CreateLinkResponse:
      type: object
      required:
        - code
        - shortUrl
      additionalProperties: false
      properties:
        code:
          type: string
          description: The short code (the requested alias, or an auto-generated base62 code).
          examples:
            - "b7"
        shortUrl:
          type: string
          format: uri
          description: The absolute short URL, built from server-side configured base URL.
          examples:
            - "https://sho.rt/b7"
    LinkStats:
      type: object
      required:
        - code
        - url
        - createdAt
        - expiresAt
        - clickCount
      additionalProperties: false
      properties:
        code:
          type: string
          examples:
            - "b7"
        url:
          type: string
          format: uri
          description: The original URL.
        createdAt:
          type: string
          format: date-time
          description: ISO-8601 UTC creation timestamp.
        expiresAt:
          type:
            - string
            - "null"
          format: date-time
          description: ISO-8601 UTC expiry timestamp, or null if none was set.
        clickCount:
          type: integer
          minimum: 0
          format: int64
    Error:
      type: object
      required:
        - error
      additionalProperties: false
      properties:
        error:
          type: string
          description: Machine-readable error message.
          examples:
            - "alias already taken"


--- docs/adr/0001-sqlite-native-concurrency.md ---
# 0001. Use SQLite's native rowid and unique constraints as the concurrency mechanism

## Context

Two acceptance criteria are concurrency-sensitive in a way that shapes the whole system:

- Criterion 13/15: auto-generated codes are base62 over a *monotonic* identifier, never reused,
  including across restarts.
- Criterion 14: two concurrent `POST /api/v1/links` requests for the same alias must resolve to
  exactly one 201 and one 409, with no duplicate rows ever existing for that alias.

Something has to own "the next id" and "is this alias already taken" as atomic decisions. Where
that authority lives — in the application process, in a separate allocator, or in the database
itself — determines the shape of the repository layer, whether the service can ever run as more
than one process against the same data, and how much custom locking code this run has to write
and maintain. This is the single decision everything else in the design leans on: the data model
(nullable `code` column to allow the two-phase auto-generate insert), the repository's transaction
boundaries, and the deployment shape (single process, one SQLite file) all follow from it.

## Decision

Use SQLite's own `INTEGER PRIMARY KEY AUTOINCREMENT` rowid as the monotonic identifier, and a
database-level `UNIQUE` index on the `code` column as the sole authority on alias/code conflicts.
The application never maintains its own counter and never does a "check if alias exists, then
insert" sequence in application code; it always attempts the insert and lets SQLite's own
constraint enforcement decide, catching `SQLITE_CONSTRAINT` and mapping it to "already taken".
Click-count increments are likewise a single atomic `UPDATE ... SET click_count = click_count + 1`
statement, never a read-then-write pair spanning two round trips.

## Alternatives considered

**Application-level in-memory counter** (e.g. an `Interlocked`-guarded `long`, seeded from
`MAX(id)` at startup) for id generation, with an in-process lock or concurrent dictionary guarding
alias uniqueness.
Rejected because: seeding from `MAX(id)` at startup has an unavoidable race window against a
second instance (or a second startup) doing the same, which is exactly the kind of duplicate-code
bug criterion 13 is testing for; and because it only works at all if there is ever exactly one
process and it never restarts mid-flight without re-seeding, which is a fragile invariant to rely
on when SQLite already offers this guarantee for free at the file level.

**A separate sequence/counter table**, updated in its own transaction immediately before every
insert, with an explicit row-level lock.
Rejected because: it adds a second write and a second point of failure per request (the counter
update can succeed while the subsequent insert fails, or vice versa, needing careful transaction
scoping to avoid it) to reproduce a guarantee `AUTOINCREMENT` already provides atomically as part
of the same insert. It also does nothing extra for the alias-uniqueness half of criterion 14,
which still needs a unique index regardless.

**Random/UUID-based codes instead of monotonic base62.**
Not a real contender here since the requirement explicitly mandates "base62 over a monotonic
identifier" — noted only to record that it was not considered a viable alternative, not evaluated
on its own merits.

**External allocator or distributed sequence (e.g. a Redis `INCR`, or a separate id service).**
Rejected because: it introduces a second moving part and a second failure mode (network call,
separate process to keep running) for a single-node service where SQLite is already the mandated
system of record; nothing in the requirement anticipates multiple service instances sharing one
database, so the coordination problem this would solve does not exist yet.

## Consequences

- The repository layer is simpler than any of the alternatives: "attempt the write, interpret the
  constraint violation if any" replaces separate check-then-act logic, and there is less
  concurrency-control code to test and get wrong.
- The service can only ever run as a single process against a given SQLite file. This is a real
  ceiling: horizontal scaling of the write path is not possible without a different persistence
  choice later, and that migration is not free — it would mean revisiting this decision entirely.
  Nothing in the current requirement asks for multi-instance operation, so this is accepted rather
  than designed around now.
- The two-phase insert for auto-generated codes (insert with `code = NULL`, then `UPDATE` once the
  rowid is known) requires the `code` column to be nullable, which is a slightly unusual shape for
  a column that is conceptually "always eventually set" — a reader of the schema alone has to know
  why `code` can be `NULL` even though every settled row has one. This is documented in the design
  doc's data model section precisely because it is not self-explanatory.
- Because SQLite serializes writers, no additional application-level locking (mutex, semaphore) is
  needed anywhere in the service; correctness under concurrency is inherited from the database
  rather than hand-built, which is both the main appeal of this decision and the main reason it
  could look, to someone unfamiliar with SQLite's write model, like a service with no concurrency
  handling at all.


--- docs/ambiguity.md ---
# Ambiguity Report: URL Shortener Service

## Score: 0.3 (real gaps, buildable with documented assumptions)

No single gap here forces a stop: the request is precise about HTTP status codes, validation scope, and persistence mechanism. The gaps below are genuine, and one or two touch security/data posture, but each has a conventional, defensible default a competent engineer would pick and record rather than block on. That places this in the 0.3-0.5 band rather than the 0.6+ band.

---

### 1. "It returns 201 with the short code and the absolute short URL."

The request does not say what host/scheme the "absolute short URL" should use.

- **Interpretation A**: The service has a configured base URL (e.g. `SHORT_URL_BASE=https://sho.rt`) and always builds `shortUrl` from it.
- **Interpretation B**: The service derives the base URL from the incoming request's `Host`/`X-Forwarded-Host` header at request time.

Under A, the service needs deployment configuration and returns a stable URL regardless of how it was reached. Under B, the returned `shortUrl` reflects whatever host the client used to call the API, which is more "automatic" but means the response is trivially influenced by the `Host` header a client sends -- a spoofable input if the service sits behind a misconfigured proxy. This is a security/config-shape decision, not just a detail, because switching from B to A after clients start relying on returned URLs is a compatibility-breaking change.

**Assumption taken**: Interpretation A (configured base URL), recorded as a non-material default in the spec, because it is the safer and more conventional choice and does not require asking a human to proceed.

---

### 2. "Reject with 400 any URL whose host is an IP literal in a loopback, link-local, or RFC 1918 private range."

RFC 1918 is an IPv4-specific term. The request never mentions IPv6.

- **Interpretation A**: Only IPv4 literal ranges are checked; an IPv6 literal like `http://[::1]/` or `http://[fc00::1]/` would be accepted, since the request's ranges are all IPv4.
- **Interpretation B**: The intent is SSRF protection in general, so the equivalent IPv6 ranges (`::1`, `fe80::/10`, `fc00::/7`) should also be blocked even though not named.

These produce materially different security postures: A leaves an SSRF-style bypass via IPv6 literals; B closes it. This is a security-relevant silent-default situation, which is why it is flagged rather than waved through, but a competent engineer would default to the safer reading (B) and document it rather than stopping the pipeline to ask, since the cost of being wrong is a documented assumption, not an unrecoverable design fork.

**Assumption taken**: Interpretation B (block IPv6 equivalents too), recorded in the spec.

---

### 3. "A requested alias that is already taken returns 409."

The request never states whether an alias becomes available again once its link has expired.

- **Interpretation A**: Alias uniqueness is permanent -- once used, never reusable, even after the link expires (soft-expiry model; expiry only affects the redirect/access path).
- **Interpretation B**: An expired link's alias is implicitly released and can be claimed by a new `POST` (expiry model with reclaim).

These are different products: B requires either deleting/soft-deleting expired rows on some trigger, or excluding expired rows from the uniqueness check, which changes the data model and the guarantees `GET /{code}/stats` can offer for old links (looking up an expired-and-reclaimed code would now show the *new* link, silently losing history). This is the kind of behavior a requester could be surprised by, and reversing it later (once clients depend on either behavior) is expensive.

**Assumption taken**: Interpretation A (aliases are permanent, no reclaim), recorded as the default since it preserves historical integrity and is the safer of the two to build first.

---

### 4. "GET /api/v1/links/{code}/stats returns ... the click count."

The request does not say what this endpoint returns once a link has expired.

- **Interpretation A**: Stats endpoint ignores expiry and always returns `200` with the data (introspection endpoint, independent of the redirect gate).
- **Interpretation B**: Stats endpoint mirrors the redirect endpoint's expiry semantics and returns `410` for expired links.

A makes the stats endpoint useful for auditing after expiry (e.g., "how many clicks did this get before it expired"); B makes `/stats` consistent with `/{code}` but destroys the ability to audit expired links via the API. This changes what the endpoint is *for*.

**Assumption taken**: Interpretation A (stats always available regardless of expiry), recorded as the default, as it is the more generally useful and less surprising behavior for an introspection endpoint.

---

### 5. "expiresAt (optional, ISO-8601 UTC)"

No statement of whether a past-dated `expiresAt` at creation time is valid.

- **Interpretation A**: Any syntactically valid ISO-8601 UTC timestamp is accepted, including ones in the past; the link is simply born expired (immediately returns 410 on access).
- **Interpretation B**: `expiresAt` must be in the future; a past timestamp returns `400`.

This affects validation logic and test expectations but does not change the shape of the system -- either way is a small, reversible validation rule.

**Assumption taken**: Interpretation A (accept past timestamps, link is born expired), recorded as a non-material default; noted here because it is a real fork even though it does not rise to material.

---

## Non-material items (recorded as assumptions in the spec, not analyzed further here)

- Alias allowed character set and length limits.
- Exact JSON error-body shape for 400/404/409/410 responses.
- Whether click-count increments are logged/audited beyond the counter itself.
- Base62 alphabet ordering / which 62 characters are used.
- Whether `HEAD` requests to `/{code}` also increment click count (assumed: only `GET` is specified, so only `GET` increments).


--- docs/design.md ---
# Design: URL Shortener Service

## 1. Overview

A single ASP.NET Core (minimal API) process, backed by one SQLite database file, that creates
short links, redirects them, and reports per-link statistics. There is no auth, no multi-tenant
namespace, no editing/deletion, and no DNS resolution anywhere in the request path — all per the
requirement and the recorded assumptions in `docs/requirements.md`.

The system is deliberately small: one process, one writer, one table. Nothing here anticipates
future scale, multi-region deployment, or a second link namespace; those are not in the
requirement and are not designed for.

## 2. Components

**API Host** (`Program.cs` + endpoint handlers)
Owns HTTP routing, request/response shaping, and status-code selection (201/302/400/404/409/410).
Translates domain results from the Link Service into HTTP responses. Holds no business logic
itself — a handler that has to decide *why* something failed belongs in the Link Service, not
here.

**Request Validator**
Parses and validates the incoming JSON body for `POST /api/v1/links`: `url` is present and a
syntactically valid absolute URI; `alias`, if present, matches the allowed character set
(`[A-Za-z0-9_-]`, 1-32 chars); `expiresAt`, if present, parses as ISO-8601 UTC. Produces 400 with
a structured `{ "error": "..." }` body before anything reaches the Link Service or the database.

**URL Safety Validator**
A pure function: given a parsed URL, rejects (400) if the scheme is not `http`/`https`, or if the
host is a literal IP (v4 or v6) in loopback, link-local, or private ranges (RFC 1918 for v4;
`::1`, `fe80::/10`, `fc00::/7` for v6, per the ambiguity report's recorded assumption). Hostnames
that are not IP literals are accepted unconditionally at this stage — no DNS lookup is ever
performed, by construction: this validator never opens a socket or calls a resolver, it only
inspects the string form of the host that the URL parser already extracted.

**Code Generator**
Encodes a `long` id (the SQLite rowid) as base62, using a fixed 62-character alphabet
(`0-9A-Za-z`, digits first). Stateless; take an id in, get a code out. Never invents or checks
uniqueness itself — that is the repository's job, backed by the unique index.

**Link Repository**
The only component that talks to SQLite (via `Microsoft.Data.Sqlite`, hand-written SQL — see ADR
0001 for the data-access approach). Owns the schema, the connection/transaction lifecycle, and
three operations: insert-with-alias-or-autogenerate, find-by-code, and atomic click-increment.
This is where concurrency correctness for criteria 8 and 14 actually lives — see §6.

**Link Service**
Orchestrates the above for the three use cases (create, redirect, stats). Decides which HTTP
outcome a domain outcome maps to (e.g. "alias already exists" -> conflict; "expired" -> gone) and
returns a small result type the API Host renders. This is the seam that keeps the API Host
dumb and the Repository ignorant of HTTP.

**Configuration**
One setting group: `ShortLinks:BaseUrl` (absolute scheme+host used to build `shortUrl` in create
responses, never derived from request headers — see ambiguity report item 1) and
`ShortLinks:DbPath` (SQLite file path). Read once at startup via the standard ASP.NET Core
configuration pipeline (env vars / appsettings.json), no runtime reconfiguration.

## 3. Request flow

### `POST /api/v1/links`
1. API Host reads and deserializes the body.
2. Request Validator checks `url` presence, `alias` shape, `expiresAt` parseability. Any failure
   -> 400 immediately, nothing touches the database.
3. URL Safety Validator checks scheme and literal-IP ranges on the parsed `url`. Failure -> 400.
4. Link Service asks the Repository to insert:
   - If `alias` was supplied: `INSERT INTO links(code, original_url, created_at, expires_at)
     VALUES (@alias, ...)` inside a transaction. A `SQLITE_CONSTRAINT` violation on the unique
     `code` index is caught and mapped to "alias taken" -> Link Service returns conflict -> API
     Host returns 409. Nothing is created (the transaction is rolled back by the failed insert).
   - If no `alias`: `INSERT INTO links(code, original_url, created_at, expires_at) VALUES (NULL,
     ...)` (the unique index over `code` permits multiple NULLs in SQLite), then
     `last_insert_rowid()` is read, the id is base62-encoded, and `UPDATE links SET code = @code
     WHERE id = @id` is run, all inside the same transaction. This makes "reserve an id" and
     "assign its code" atomic with respect to any other writer, and ties the generated code
     directly to the monotonic rowid (criterion 13).
5. On success: 201 with `{ "code": ..., "shortUrl": BaseUrl + "/" + code }`.

### `GET /{code}`
1. Link Service asks the Repository for the row by code.
2. Not found -> 404.
3. Found but `expires_at <= now (UTC)` -> 410, click count **not** touched (a single `SELECT`
   decides this before any write is attempted).
4. Otherwise: repository runs `UPDATE links SET click_count = click_count + 1 WHERE code = @code`
   (an atomic read-modify-write done entirely inside SQLite, not in application memory) and the
   API Host returns 302 with `Location: original_url`.

### `GET /api/v1/links/{code}/stats`
1. Repository looks up by code.
2. Not found -> 404.
3. Found (expired or not — per the recorded assumption that stats are an introspection endpoint,
   independent of the redirect gate) -> 200 with `code`, `url`, `createdAt`, `expiresAt`
   (`null` if unset), `clickCount`.

## 4. Data model

One table, one file, one process. This is the entire system of record.

```sql
CREATE TABLE links (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    code         TEXT UNIQUE,              -- NULL only transiently during auto-generate insert
    original_url TEXT NOT NULL,
    created_at   TEXT NOT NULL,             -- ISO-8601 UTC, e.g. 2024-01-01T00:00:00Z
    expires_at   TEXT,                      -- ISO-8601 UTC, NULL if no expiry
    click_count  INTEGER NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX idx_links_code ON links(code);
```

- `id` is the monotonic identifier the requirement asks for; SQLite's `AUTOINCREMENT` guarantees
  it is never reused, even across restarts (tracked in SQLite's internal `sqlite_sequence` table),
  which is what criterion 13's "no two links ever receive the same code" and "determinism across
  restarts" (NFR) rest on.
- `code` is the single namespace both aliases and auto-generated codes live in (per the recorded
  assumption that both are looked up via the same `GET /{code}` route), enforced as unique at the
  database level, not just in application logic — this is what makes criterion 14 (concurrent
  identical-alias requests) resolve to exactly one 201 and one 409 rather than a logic race.
- Timestamps are stored as ISO-8601 UTC text rather than SQLite's native (limited) datetime
  affinity, so that string comparison (`expires_at <= @now`) is monotonic and unambiguous, and so
  the same representation round-trips to JSON without conversion.

## 5. Where state lives

All state — links, click counts, the monotonic id sequence — lives in the one SQLite file at
`ShortLinks:DbPath`. The process itself is stateless between requests: no in-memory cache of
links, no in-memory counter for id generation (see ADR 0001 for why). This means the service can
be stopped and restarted with no special shutdown sequence and no state to reconcile — the file
on disk is authoritative the instant a transaction commits. It also means exactly one process may
safely run against a given database file: SQLite's single-writer model is a property of the file,
not something this design adds on top of it (WAL mode is enabled so readers do not block on the
writer, but there is still one writer at a time).

## 6. How the design meets each acceptance criterion

1. Valid `url`, no `alias` -> 201 + generated `code`/`shortUrl`, row persisted: §3 create flow,
   step 4 (auto-generate branch).
2. Valid `url` + free `alias` -> 201, `code` == alias: §3 create flow, step 4 (alias branch).
3. Alias already taken -> 409, no row created: unique index on `code` + `SQLITE_CONSTRAINT`
   catch, transaction rolled back (§3, §4).
4. Missing `url` -> 400: Request Validator, before any DB access (§2, §3).
5. Non-http/https scheme -> 400: URL Safety Validator (§2).
6. Literal private/loopback/link-local IP host (v4 and v6) -> 400, no DNS lookup: URL Safety
   Validator inspects only the parsed literal host string; no resolver is ever invoked (§2).
7. Invalid/non-ISO-8601 `expiresAt` -> 400: Request Validator (§2, §3).
8. `GET /{code}` valid+unexpired -> 302 with stored URL, click count +1 exactly once: atomic
   `UPDATE ... SET click_count = click_count + 1` inside SQLite (§3, §4).
9. Unknown code -> 404: repository lookup miss (§3).
10. Expired code -> 410, no increment: expiry checked in a read before any write is attempted
    (§3).
11. Stats for existing code -> 200 with the five fields: repository lookup + direct field mapping
    (§3).
12. Stats for unknown code -> 404: same lookup-miss path as (9).
13. Auto-generated codes are base62(monotonic id), no collisions: `AUTOINCREMENT` rowid feeding
    the Code Generator, id never reused (§4).
14. Concurrent identical-alias POSTs -> exactly one 201, one 409, no duplicate rows: DB-level
    unique constraint on `code`, not an application-level check-then-insert (§3, §4). SQLite
    serializes the two writers; the second insert observes the constraint violation.
15. Data survives restart: SQLite file is the sole store, `AUTOINCREMENT` sequence persisted in
    the same file, no in-memory state to lose (§5).

## 7. Failure modes designed for

- **Concurrent alias creation race** (criterion 14): resolved at the database layer via a unique
  index, not via an application-level "check then insert" that would have a TOCTOU race window.
- **Concurrent click increments**: resolved via a single atomic `UPDATE ... SET x = x + 1` SQL
  statement rather than a read-in-app/increment-in-app/write-back sequence, which would lose
  increments under concurrency.
- **Restart durability and id-reuse**: relies on SQLite's on-disk `AUTOINCREMENT` sequence rather
  than an in-memory counter, so a restart cannot produce a duplicate code.
- **Host-header spoofing of the returned `shortUrl`**: the base URL is fixed server-side
  configuration, never read from `Host`/`X-Forwarded-Host`, so a client cannot influence what
  short URL other clients are told to trust.
- **IPv6 SSRF bypass**: the requirement names only IPv4 ranges; the validator also blocks the
  IPv6 loopback/link-local/unique-local equivalents, closing the gap the ambiguity report flagged,
  since the intent is clearly SSRF protection rather than an IPv4-only rule.
- **Malformed/partial input reaching the database**: all input validation happens before any SQL
  is issued, so a bad request cannot create a partial or inconsistent row.

## 8. Failure modes knowingly left

- **SSRF via redirect chains or DNS rebinding**: this design checks only the literal host string
  submitted at creation time, exactly as the requirement specifies ("do not perform DNS
  resolution"). A hostname that resolves to a private address at redirect time — or an
  externally-hosted URL that itself redirects to an internal address — is not, and cannot be,
  caught by this design. This is a real gap in general SSRF protection; it is explicitly out of
  scope per the requirement text and the requirements doc's "out of scope" section, not an
  oversight.
- **SQLite as a throughput ceiling**: one writer at a time means write throughput is bounded by
  SQLite's single-writer model. No NFR gives a target request rate, so this is accepted rather
  than designed around (e.g. no sharding, no queue-based write-batching).
- **No backup/replication**: the database file is a single point of failure for durability beyond
  "survives a process restart" (criterion 15). Disk loss loses all links. Nothing in the
  requirement asks for backup or replication, so none is designed.
- **Alias squatting**: because aliases are permanent (never reclaimed, per the recorded
  assumption), a client can permanently reserve a desirable alias with a short-lived or
  immediately-expired link. This is accepted as the cost of the simpler, audit-preserving model
  and is not mitigated (no deletion feature exists, and none was requested).
- **No rate limiting**: a client can create unbounded links or hammer redirects; explicitly out
  of scope per the requirements doc.


