public sealed class CodeGeneratorTests
{
    [Fact]
    public void Encode_zero_returns_single_zero_character()
    {
        string result = CodeGenerator.Encode(0);
        Assert.Equal("0", result);
    }

    [Fact]
    public void Encode_one_returns_single_one_character()
    {
        string result = CodeGenerator.Encode(1);
        Assert.Equal("1", result);
    }

    [Fact]
    public void Encode_nine_returns_single_nine_character()
    {
        string result = CodeGenerator.Encode(9);
        Assert.Equal("9", result);
    }

    [Fact]
    public void Encode_ten_returns_A()
    {
        string result = CodeGenerator.Encode(10);
        Assert.Equal("A", result);
    }

    [Fact]
    public void Encode_61_returns_lowercase_z()
    {
        string result = CodeGenerator.Encode(61);
        Assert.Equal("z", result);
    }

    [Fact]
    public void Encode_62_returns_two_character_code_10()
    {
        string result = CodeGenerator.Encode(62);
        Assert.Equal("10", result);
    }

    [Fact]
    public void Encode_3843_returns_ZZ()
    {
        // 62^2 - 1 = 3843
        string result = CodeGenerator.Encode(3843);
        Assert.Equal("zz", result);
    }

    [Fact]
    public void Encode_3844_returns_100()
    {
        string result = CodeGenerator.Encode(3844);
        Assert.Equal("100", result);
    }

    [Fact]
    public void Encode_is_monotonic_for_sequential_ids()
    {
        string prev = CodeGenerator.Encode(0);
        for (long i = 1; i <= 100; i++)
        {
            string current = CodeGenerator.Encode(i);
            // Just verify it encodes without error and produces a string
            Assert.NotNull(current);
            Assert.NotEmpty(current);
            // Numeric comparison of base62 strings is not guaranteed to work,
            // so we just verify the sequence is deterministic
            prev = current;
        }
    }

    [Fact]
    public void Encode_large_id_produces_valid_base62()
    {
        long largeId = 999999999999999L;
        string result = CodeGenerator.Encode(largeId);
        Assert.NotNull(result);
        Assert.NotEmpty(result);
        // Verify all characters are in the base62 alphabet
        foreach (char c in result)
        {
            Assert.True(char.IsLetterOrDigit(c) || c == '_' || c == '-' ||
                       (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'));
        }
    }

    [Fact]
    public void Encode_same_id_always_produces_same_code()
    {
        long id = 12345;
        string result1 = CodeGenerator.Encode(id);
        string result2 = CodeGenerator.Encode(id);
        Assert.Equal(result1, result2);
    }
}
